sealed class T_MessageEntity : TlObject {
    companion object {
        fun read(r: TlReader): T_MessageEntity {
            return when (val id = r.int32()) {
                0xbb92ba95.toInt() -> C_messageEntityUnknown.read(r)
                0xfa04579d.toInt() -> C_messageEntityMention.read(r)
                0x6f635b0d.toInt() -> C_messageEntityHashtag.read(r)
                0x6cef8ac7.toInt() -> C_messageEntityBotCommand.read(r)
                0x6ed02538.toInt() -> C_messageEntityUrl.read(r)
                0x64e475c2.toInt() -> C_messageEntityEmail.read(r)
                0xbd610bc9.toInt() -> C_messageEntityBold.read(r)
                0x826f8b60.toInt() -> C_messageEntityItalic.read(r)
                0x28a20571.toInt() -> C_messageEntityCode.read(r)
                0x73924be0.toInt() -> C_messageEntityPre.read(r)
                0x76a6d327.toInt() -> C_messageEntityTextUrl.read(r)
                0xdc7b1140.toInt() -> C_messageEntityMentionName.read(r)
                0x208e68c9.toInt() -> C_inputMessageEntityMentionName.read(r)
                0x9b69e34b.toInt() -> C_messageEntityPhone.read(r)
                0x4c4e743f.toInt() -> C_messageEntityCashtag.read(r)
                0x9c4e7e8b.toInt() -> C_messageEntityUnderline.read(r)
                0xbf0693d4.toInt() -> C_messageEntityStrike.read(r)
                0x761e6af4.toInt() -> C_messageEntityBankCard.read(r)
                0x32ca960f.toInt() -> C_messageEntitySpoiler.read(r)
                0xc8cf05f8.toInt() -> C_messageEntityCustomEmoji.read(r)
                0xf1ccaaac.toInt() -> C_messageEntityBlockquote.read(r)
                0x904ac7c7.toInt() -> C_messageEntityFormattedDate.read(r)
                0x71777116.toInt() -> C_messageEntityDiffInsert.read(r)
                0xc6c1e5a7.toInt() -> C_messageEntityDiffReplace.read(r)
                0x0652c1c5.toInt() -> C_messageEntityDiffDelete.read(r)
                0xfdabbfcd.toInt() -> C_messageEntityTonAddress.read(r)
                else -> throw TlException("unknown constructor 0x${Integer.toHexString(id)} for MessageEntity")
            }
        }
    }
}

