        wr.int32(0x904ac7c7.toInt())
        wr.int32((if (relative) 1 else 0) or (if (short_time) 2 else 0) or (if (long_time) 4 else 0) or (if (short_date) 8 else 0) or (if (long_date) 16 else 0) or (if (day_of_week) 32 else 0))
