        wr.int32(length)
        wr.int32(date)
    }
    companion object {
        fun read(r: TlReader): C_messageEntityFormattedDate {
            val flags = r.int32()
            val relative = (flags and 1) != 0
            val short_time = (flags and 2) != 0
            val long_time = (flags and 4) != 0
            val short_date = (flags and 8) != 0
            val long_date = (flags and 16) != 0
            val day_of_week = (flags and 32) != 0
            val offset = r.int32()
            val length = r.int32()
            val date = r.int32()
            return C_messageEntityFormattedDate(relative = relative, short_time = short_time, long_time = long_time, short_date = short_date, long_date = long_date, day_of_week = day_of_week, offset = offset, length = length, date = date)
        }
    }
