        wr.int32(0xc9f06e1b.toInt())
        wr.int32((if (creator) 1 else 0) or (if (bot_participant) 32 else 0) or (if (has_username != null) 8 else 0) or (if (forum != null) 16 else 0) or (if (user_admin_rights != null) 2 else 0) or (if (bot_admin_rights != null) 4 else 0))
        has_username?.let { wr.bool(it) }
        forum?.let { wr.bool(it) }
        user_admin_rights?.let { it.serialize(wr) }
        bot_admin_rights?.let { it.serialize(wr) }
    }
    companion object {
        fun read(r: TlReader): C_requestPeerTypeChat {
            val flags = r.int32()
            val creator = (flags and 1) != 0
            val bot_participant = (flags and 32) != 0
            val has_username = if ((flags and 8) != 0) r.bool() else null
            val forum = if ((flags and 16) != 0) r.bool() else null
            val user_admin_rights = if ((flags and 2) != 0) T_ChatAdminRights.read(r) else null
            val bot_admin_rights = if ((flags and 4) != 0) T_ChatAdminRights.read(r) else null
            return C_requestPeerTypeChat(creator = creator, bot_participant = bot_participant, has_username = has_username, forum = forum, user_admin_rights = user_admin_rights, bot_admin_rights = bot_admin_rights)
        }
    }
}

