            val gift = if ((flags and 512) != 0) T_StarGift.read(r) else null
            return C_wallet_nftItem(collection_address = collection_address, address = address, owner_address = owner_address, index = index, name = name, description = description, image = image, image_small = image_small, content_url = content_url, lottie = lottie, attributes = attributes, extra = extra, gift = gift)
        }
    }
}

